%%\ Lab 2: 2D Convolution & FIR Filters (Blur, Sharpen, Edges)
% Course: Mathematical Algorithms (DSP) — Image Processing Labs
close all; clear; clc;

if ~exist('screenshots', 'dir')
    mkdir('screenshots');
end

if exist('peppers.png', 'file')
    I0 = imread('peppers.png');
else
    I0 = repmat(imread('cameraman.tif'), 1, 1, 3);
end
I = im2double(rgb2gray(I0));

%%\ 1) Delta image & impulse response
delta = zeros(101, 101); delta(51, 51) = 1;
h_avg = ones(3, 3) / 9;
H_vis = conv2(delta, h_avg, 'same');

f1 = figure; %[output:495fb6e1]
imagesc(H_vis); axis image off; colorbar; %[output:495fb6e1]
title('Impulse response of 3x3 average'); %[output:495fb6e1]
saveas(f1, fullfile('screenshots', '01_impulse_response.png')); %[output:495fb6e1]

%%\ 2) Low-pass: box vs Gaussian, separability
h_box3 = ones(3, 3) / 9;
h_box7 = ones(7, 7) / 49;
sigma = 1.2;
g1d = fspecial('gaussian', [1 7], sigma);
h_gauss = g1d' * g1d; % separable 2D kernel

I_box3  = imfilter(I, h_box3, 'replicate');
I_box7  = imfilter(I, h_box7, 'replicate');
I_gauss = imfilter(I, h_gauss, 'replicate');

% Verify two 1D passes match the 2D separable kernel
I_gauss_1d = imfilter(imfilter(I, g1d, 'replicate'), g1d', 'replicate');
fprintf('Max difference (2D Gaussian vs two 1D passes): %g\n', max(abs(I_gauss(:) - I_gauss_1d(:)))); %[output:03d828d4]

f2 = figure; %[output:06da853a]
montage({I, I_box3, I_box7, I_gauss}, 'Size', [1 4]); %[output:06da853a]
title('Original | Box 3x3 | Box 7x7 | Gaussian (separable)'); %[output:06da853a]
saveas(f2, fullfile('screenshots', '02_lowpass_filters.png')); %[output:06da853a]

%%\ 3) Unsharp masking (sharpen)
I_blur  = imfilter(I, h_gauss, 'replicate');
mask    = I - I_blur; % high-frequency detail
gain    = 1.0;
I_sharp = max(min(I + gain * mask, 1), 0);

f3 = figure; %[output:3383fbe9]
montage({I, I_blur, mask, I_sharp}, 'Size', [1 4]); %[output:3383fbe9]
title('Original | Blur | High-freq mask | Sharpened'); %[output:3383fbe9]
saveas(f3, fullfile('screenshots', '03_unsharp_masking.png')); %[output:3383fbe9]

%%\ 4) Edges: Sobel & Laplacian
h_sobel_x = fspecial('sobel');
h_sobel_y = h_sobel_x';
Gx   = imfilter(I, h_sobel_x, 'replicate');
Gy   = imfilter(I, h_sobel_y, 'replicate');
Gmag = hypot(Gx, Gy);

h_lap = fspecial('laplacian', 0.2);
I_lap = imfilter(I, h_lap, 'replicate');

f4 = figure; %[output:977b94f4]
montage({mat2gray(Gx), mat2gray(Gy), mat2gray(Gmag), mat2gray(I_lap)}, 'Size', [1 4]); %[output:977b94f4]
title('Sobel Gx | Sobel Gy | Gradient magnitude | Laplacian'); %[output:977b94f4]
saveas(f4, fullfile('screenshots', '04_edges_sobel_laplacian.png')); %[output:977b94f4]

%%\ 5) Correlation vs convolution (kernel flip)
C1 = conv2(I, h_box3, 'same');
C2 = imfilter(I, h_box3, 'conv', 'same'); % 'conv' flips kernel internally
diff_val = max(abs(C1(:) - C2(:)));
fprintf('Max difference (conv2 vs imfilter with conv): %g\n', diff_val); %[output:569d20ad]

%%\ 6) Boundary handling
I_rep = imfilter(I, h_box7, 'replicate');
I_sym = imfilter(I, h_box7, 'symmetric');
I_cir = imfilter(I, h_box7, 'circular');

f6 = figure; %[output:0a3b31c6]
montage({I_rep, I_sym, I_cir}, 'Size', [1 3]); %[output:0a3b31c6]
title('Boundary: replicate | symmetric | circular'); %[output:0a3b31c6]
saveas(f6, fullfile('screenshots', '06_boundary_handling.png')); %[output:0a3b31c6]

